add('beach','explore','День у океана',10,140,'Даже в Los Santos можно никуда не торопиться.', ['Вместе доберитесь до пляжа Del Perro.','Найдите красивое место с видом на океан и припаркуйтесь.','Сделайте общий скриншот рядом с машиной.'], 'По пути каждый выбирает одну остановку, которую обычно проезжает мимо.')
add('garage','chaos','Самый странный экипаж',8,130,'Побеждает не самая быстрая машина, а самая смешная история.', ['Первый игрок выбирает через M обычную, но нелепую машину.','Второй придумывает ей имя и цель поездки.','Доедьте до выбранной точки и расскажите друг другу, кем работает этот экипаж.'], 'Выбор нельзя обсуждать заранее. После финиша — общее фото.')
add('parking','road','Легенды парковки',5,90,'Знакомая парковка превращается в площадку точного вождения.', ['Найдите три свободных парковочных места в хабе.','Первый паркуется передом, второй — задним ходом.','Повторите на другой машине и выберите самый аккуратный заезд.'], 'Пассажир — инструктор: помогает словами, а не управлением.')
add('tour','explore','Три открытки',12,170,'Создайте маленький альбом вашего вечера.', ['Выберите три разных места: город, природа и вода.','Посетите их вместе, не возвращаясь в хаб между точками.','Сделайте по общему снимку в каждом месте.'], 'На каждом фото один придумывает название, другой — смешную подпись.')
add('courier','road','Эстафета курьеров',8,120,'Один маршрут, два водителя, ни одного потерянного пассажира.', ['Выберите на карте треугольник из трёх близких точек.','Проедьте первый участок, затем поменяйтесь местами.','Третий участок ведёт тот, кто сделал меньше остановок не по делу.'], 'Меняться местами можно только в полностью остановившейся машине.')
add('silent','team','Пять минут без GPS',5,100,'Проверьте, насколько хорошо вы уже узнаёте город.', ['Пассажир называет известное место, например пирс или обсерваторию.','Водитель ищет дорогу без большой карты.','Если заблудились, пассажир может дать ровно три подсказки.'], 'В конце сравните реальный маршрут с тем, который вы представляли.')
add('sunset','explore','Город с высоты',12,160,'Найдите место, где Los Santos помещается в один кадр.', ['Доедьте до обсерватории Galileo или другой доступной смотровой площадки.','Пройдите последний участок пешком вдвоём.','Выберите лучший ракурс и сделайте скриншот.'], 'Пусть навигатор выбирает необычный обратный путь.')
