add('swap','road','На другом месте',8,120,'Узнайте, как брат видит вашу обычную поездку.', ['Выберите короткий маршрут от хаба до магазина и обратно.','Первую половину ведёт один, вторую — другой.','Каждый даёт одну полезную подсказку и отмечает один удачный момент.'], 'Без соревнования: цель — сделать следующую поездку приятнее для обоих.')
add('landmark','explore','Секретная открытка',9,130,'Найдите место по описанию, а не по точке.', ['Один выбирает место в городе и описывает три заметные детали.','Второй предлагает версию и ведёт экипаж.','Если угадали — общий снимок; если нет — автор описания ведёт вас к ответу.'], 'Не выбирайте закрытые сюжетные интерьеры: подойдут доступные улицы и площади.')
add('slow','road','Самая спокойная погоня',6,100,'Город шумит, но вы никуда не опаздываете.', ['Выберите две близкие точки и проедьте маршрут без столкновений.','На каждом перекрёстке пассажир заранее говорит следующий манёвр.','В конце поменяйтесь местами и повторите.'], 'Победа общая, если оба заезда получились аккуратными.')
add('movie','chaos','Трейлер вашего фильма',10,150,'У вас есть город, две роли и один дубль.', ['Выберите жанр: комедия, детектив или приключение.','Придумайте завязку в одном предложении.','Сыграйте три короткие сцены в трёх доступных местах города.'], 'Финальная сцена обязательно заканчивается словами: «Завтра продолжим».')
add('roadtrip','explore','Маленькое большое путешествие',18,220,'Оставьте центр и устройте совместную вылазку.', ['Выберите Sandy Shores или Paleto Bay.','Возьмите подходящую машину, запаситесь здоровьем и бронёй.','По дороге остановитесь в двух местах и доберитесь до общей цели.'], 'Обратный путь можно оставить на следующий раунд — торопиться не обязательно.')
add('twofinds','team','Два коллекционера',8,120,'Каждый приносит в вечер что-то своё.', ['Каждый выбирает по одному доступному месту недалеко от хаба.','Сначала едете к выбору первого, затем ко второму.','На месте объясните, чем оно вам понравилось.'], 'Не оценивайте выбор: найдите в каждом месте одну неожиданную деталь.')
add('photos','chaos','Рекламная кампания',8,120,'Обычная машина получает невероятную историю.', ['Выберите самый обычный автомобиль.','Сделайте три рекламных кадра: деловой, приключенческий и совершенно нелепый.','Придумайте название модели и рекламный слоган.'], 'Один — фотограф, другой — постановщик. После каждого кадра меняетесь.')
add('mountain','road','Штурман горных дорог',15,200,'Спокойное вождение здесь важнее мощности.', ['Выберите доступный горный маршрут и подходящую машину.','Штурман предупреждает о крутых поворотах и предлагает места для остановок.','Доберитесь до красивой точки и вернитесь к ближайшей дороге.'], 'Если стало неудобно ехать — вместе решаете развернуться, это тоже успешное приключение.')
add('home','team','Возвращение домой',7,100,'Хороший вечер заслуживает общего финала.', ['Встретьтесь у вашей парковки.','Почините машину, восстановите здоровье и броню.','Каждый выбирает лучший момент сегодняшней игры.'], 'Сохраните одну общую победу в журнале и придумайте цель на следующий вечер.')
add('champion','chaos','Чемпион по нелепым маршрутам',8,130,'Навигатор получает три желания.', ['Пассажир задаёт три условия: например мост, тоннель и вид на воду.','Водитель строит один маршрут, который выполняет все три.','В конце вместе решаете, какое условие получилось самым смешным.'], 'Точки можно менять по общему согласию: главное — поездка, а не спор.')
add('race','road','Экспресс-гонка',12,180,'Готовый экспериментальный маршрут для двоих.', ['Запустите экспериментальный профиль сервера.','Первый игрок открывает F7 и выбирает City Sprint.','Возьмите машины и пройдите маршрут оба, а не только победитель.'], 'Общая победа засчитывается, когда финишировали оба.',True)
add('parcels','team','Посылки на двоих',10,160,'Город приготовил вам небольшую совместную охоту.', ['В экспериментальном профиле первый игрок выбирает F7 → Parcel Hunt.','Разделите между собой ближайшие метки.','Собирайте посылки кнопкой E или крестовиной вниз.'], 'Последнюю посылку забираете вместе.',True)
add('targets','team','Сработанная команда',15,200,'Тир, в котором важна общая цель.', ['В экспериментальном профиле выберите F7 → Target Rush.','Вместе доберитесь до аэродрома и зелёной площадки.','По очереди закрывайте оставшиеся мишени.'], 'После каждого попадания стрелявший выбирает следующую цель для брата.',True)
add('rocket','chaos','Очень необычное такси',10,160,'Теперь привычный маршрут выглядит совсем иначе.', ['В экспериментальном профиле возьмите Rocket Voltic или Vigilante у специальной точки.','Выберите знакомый маршрут до пляжа или магазина.','Доедьте туда, поменяйтесь водителем и вернитесь.'], 'Эффектные способности используйте только там, где оба готовы к неожиданностям.',True)
core=r'''
(function(root){
'use strict';
const cards=__CARDS__;
const categories={road:'За рулём',explore:'Открывать город',team:'Работать вместе',chaos:'Немного безумия'};
function cleanName(value,fallback){return typeof value==='string'&&value.trim()?value.trim().slice(0,24):fallback;}
function pool(category,experimental,short){return cards.filter(c=>(category==='all'||c.category===category)&&(!c.experimental||experimental)&&(!short||c.minutes<=10));}
function pick(list,recent,rng=Math.random){if(!list.length)return null;const fresh=list.filter(c=>!recent.includes(c.id));const p=fresh.length?fresh:list;const n=Math.max(0,Math.min(.999999,Number(rng())||0));return p[Math.floor(n*p.length)];}
function remaining(timer,now){if(!timer)return 0;return Math.max(0,Math.min(3600000,timer.running?timer.end-now:timer.left));}
function defaultState(){return {names:['Первый брат','Второй брат'],category:'all',experimental:false,short:false,turn:0,recent:[],history:[],active:null,timer:null};}
function restore(value,now){const out=defaultState();if(!value||typeof value!=='object')return out;
 out.names=[cleanName(value.names&&value.names[0],out.names[0]),cleanName(value.names&&value.names[1],out.names[1])];
 if(value.category==='all'||Object.prototype.hasOwnProperty.call(categories,value.category))out.category=value.category;
 out.experimental=value.experimental===true;out.short=value.short===true;
 out.turn=Number.isSafeInteger(value.turn)&&value.turn>=0?value.turn:0;
 out.recent=Array.isArray(value.recent)?value.recent.filter(id=>cards.some(c=>c.id===id)).slice(-8):[];
 out.history=Array.isArray(value.history)?value.history.filter(h=>h&&cards.some(c=>c.id===h.id)&&Number.isFinite(h.at)&&h.at>=0).slice(-1000).map(h=>({id:h.id,at:h.at})):[];
 if(typeof value.active==='string'&&cards.some(c=>c.id===value.active))out.active=value.active;
 if(out.active&&value.timer&&typeof value.timer==='object'){
 const t=value.timer;
 if(typeof t.running==='boolean'&&Number.isFinite(t.left)&&t.left>=0&&t.left<=3600000&&(!t.running||Number.isFinite(t.end))){
  const left=remaining(t,now);out.timer={running:t.running&&left>0,left,end:now+left};
 }}return out;
}
function complete(state,now){if(!state.active)return false;state.history.push({id:state.active,at:now});state.history=state.history.slice(-1000);state.active=null;state.timer=null;state.turn++;return true;}
function stats(history){return {wins:history.length,points:history.reduce((sum,h)=>sum+(cards.find(c=>c.id===h.id)||{points:0}).points,0)};}
root.BrothersAdventureCore={cards,categories,cleanName,pool,pick,remaining,defaultState,restore,complete,stats};
})(globalThis);
'''.replace('__CARDS__',json.dumps(cards,ensure_ascii=False))
html=(root/'template.html').read_text().replace('__CORE__',core)
(root/'Вечер-для-двоих.html').write_text(html)
(root/'core-test.js').write_text(core+'\nmodule.exports=globalThis.BrothersAdventureCore;\n')
print('Built',len(cards),'adventures')
